import { readFileSync } from "node:fs";
import { pathToFileURL } from "node:url";
const PRODUCTION = "D:/projexts/moe-next/apps/daemon/src/orchestrator/seat-output-tail.ts";
const { createStreamJsonReport } = await import(pathToFileURL(PRODUCTION).href);
const dir = process.argv[2] ?? ".";
let cases = 0; let failures = 0;
for (const mode of ["ok", "429"]) {
  const stream = readFileSync(`${dir}/sj-${mode}.out`);
  const text = readFileSync(`${dir}/text-${mode}.out`);
  for (const size of [1, 7, 4096]) {
    const report = createStreamJsonReport(); const out = []; let pushes = 0;
    for (let at = 0; at < stream.length; at += size) { out.push(report.push(stream.subarray(at, at + size))); pushes += 1; }
    out.push(report.flush());
    const decoded = Buffer.concat(out); const equal = decoded.equals(text);
    cases += 1; if (!equal) failures += 1;
    console.log(`${mode} size=${size} pushes=${pushes} sj=${stream.length}B text=${text.length}B decoded=${decoded.length}B equal=${equal}`);
  }
}
console.log(failures === 0 && cases === 6 ? `EQUIVALENCE HOLDS (${cases} cases)` : `EQUIVALENCE FAILED ${failures}/${cases}`);
process.exit(failures === 0 && cases === 6 ? 0 : 1);

